import { Plugin } from "@opencode/plugin"
import { Hello } from "./rpc.ts"
import { setupJJ } from "./features/jj/server.ts"
import { setupIntelligence } from "./features/intelligence/server.ts"

// Server part: runs in the OpenCode server. Its id is also the GUI's id (ctx.id).
export default Plugin.define({
  id: "jello",
  async setup(ctx) {
    await setupJJ(ctx)
    const cleanupIntelligence = await setupIntelligence(ctx)
    await ctx.rpc.register(Hello, {
      greet: async (input) => {
        const { name } = input as { name: string }

        return { text: `Hello ${name}, from the Jello server part (OpenCode ${ctx.app.version}).` }
      },
    })
    return cleanupIntelligence
  },
})

import { spawn } from "node:child_process"
import { open, realpath } from "node:fs/promises"
import { createRequire } from "node:module"
import { isAbsolute, relative, resolve } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { CancellationTokenSource, createMessageConnection, StreamMessageReader, StreamMessageWriter } from "vscode-jsonrpc/node"
import type { Plugin } from "@opencode/plugin"
import { Intelligence, lookupKinds, type HoverResult, type LookupKind, type PeekLocation, type PeekResult, type SourceDocument } from "./rpc.ts"

const require = createRequire(import.meta.url)
const limit = 500
const maxFileSize = 4 * 1024 * 1024
const supportedSource = (path: string) => /\.[cm]?[jt]sx?$/i.test(path)
const inside = (root: string, path: string) => {
  const child = relative(root, path)
  return child !== ".." && !child.startsWith("../") && !isAbsolute(child)
}

export async function readSource(path: string, signal?: AbortSignal) {
  signal?.throwIfAborted()
  const file = await open(path, "r")
  try {
    const info = await file.stat()
    if (!info.isFile() || info.size > maxFileSize) throw new Error("File view supports text files up to 4 MiB.")
    const buffer = Buffer.alloc(info.size + 1)
    let bytesRead = 0
    while (bytesRead < buffer.length) {
      signal?.throwIfAborted()
      const read = await file.read(buffer, bytesRead, buffer.length - bytesRead, bytesRead)
      if (!read.bytesRead) break
      bytesRead += read.bytesRead
    }
    if (bytesRead > info.size) throw new Error("File changed while loading the peek. Try again.")
    const text = buffer.subarray(0, bytesRead).toString("utf8")
    if (text.includes("\0")) throw new Error("Cannot peek a binary file.")
    return text
  } finally { await file.close() }
}

type Position = { line: number; character: number }
type Range = { start: Position; end: Position }
type Location = { uri: string; range: Range } | { targetUri: string; targetRange: Range; targetSelectionRange?: Range }
type PositionQuery = { path: string; line: number; character: number; expectedLine: string }
type HoverContents = string | { value: string; language?: string; kind?: string } | Array<string | { value: string; language?: string }>

export function hoverText(value: { contents: HoverContents } | null): string {
  if (!value) return ""
  const parts = Array.isArray(value.contents) ? value.contents : [value.contents]
  return parts.map((part) => typeof part === "string" ? part : part.value).join("\n\n").slice(0, 64_000)
}

export function normalizeLocations(value: Location | Location[] | null): PeekLocation[] {
  const seen = new Set<string>()
  const result: PeekLocation[] = []
  for (const item of value == null ? [] : Array.isArray(value) ? value : [value]) {
    const uri = "uri" in item ? item.uri : item.targetUri
    if (!uri.startsWith("file:")) continue
    const range = "range" in item ? item.range : item.targetSelectionRange ?? item.targetRange
    const location = { path: fileURLToPath(uri), line: range.start.line, character: range.start.character,
      endLine: range.end.line, endCharacter: range.end.character }
    const key = JSON.stringify(location)
    if (seen.has(key)) continue
    seen.add(key)
    result.push(location)
  }
  return result
}

export function createLanguageService(root: string) {
  // Resolve bundled scripts; only Node itself needs to be on PATH. OpenCode can
  // be a standalone executable, so process.execPath is not a JS runtime here.
  const child = spawn("node", [require.resolve("typescript-language-server/lib/cli.mjs"), "--stdio"], {
    cwd: root, stdio: ["pipe", "pipe", "pipe"],
  })
  const connection = createMessageConnection(new StreamMessageReader(child.stdout), new StreamMessageWriter(child.stdin))
  let stopped = false
  let stderr = ""
  child.stderr.on("data", (data) => { stderr = (stderr + data.toString()).slice(-4000) })
  const stop = () => {
    if (stopped) return
    stopped = true
    connection.dispose()
    if (child.pid && child.exitCode === null && child.signalCode === null) {
      // This server handles SIGINT by shutting down its tsserver child as well.
      child.kill("SIGINT")
      const force = setTimeout(() => child.kill("SIGKILL"), 2000)
      force.unref()
      child.once("exit", () => clearTimeout(force))
    }
  }
  child.on("error", (error) => { stderr = error.message; stop() })
  child.on("exit", stop)
  connection.onClose(stop)
  connection.onRequest("workspace/configuration", (params: { items: unknown[] }) => params.items.map(() => ({})))
  connection.listen()
  const request = async <T>(method: string, params: unknown, signal?: AbortSignal): Promise<T> => {
    if (stopped) throw new Error(`TypeScript language server stopped. ${stderr}`)
    signal?.throwIfAborted()
    const cancellation = new CancellationTokenSource()
    let rejectAbort: ((reason: unknown) => void) | undefined
    const aborted = new Promise<never>((_, reject) => { rejectAbort = reject })
    const abort = () => { cancellation.cancel(); rejectAbort?.(signal?.reason ?? new Error("Lookup cancelled")) }
    signal?.addEventListener("abort", abort, { once: true })
    let timer: ReturnType<typeof setTimeout> | undefined
    try {
      return await Promise.race([
        connection.sendRequest<T>(method, params, cancellation.token),
        aborted,
        new Promise<never>((_, reject) => {
          timer = setTimeout(() => { cancellation.cancel(); reject(new Error("Language lookup timed out. The project may still be loading; try again.")) }, 45_000)
        }),
      ])
    } catch (error) {
      if (stopped) throw new Error(`Could not run the TypeScript language server. Ensure Node.js 22.22.2+ is on the OpenCode server's PATH. ${stderr}`)
      throw error
    } finally {
      clearTimeout(timer)
      signal?.removeEventListener("abort", abort)
      cancellation.dispose()
    }
  }
  const ready = request("initialize", {
    processId: process.pid, rootUri: pathToFileURL(root).href,
    capabilities: { general: { positionEncodings: ["utf-16"] }, textDocument: {
      definition: { linkSupport: true }, typeDefinition: { linkSupport: true }, implementation: { linkSupport: true },
      hover: { contentFormat: ["plaintext", "markdown"] },
    } },
    // A syntax-only server can return a local import alias before semantic
    // loading finishes. Peeks must always use the semantic project service.
    initializationOptions: { disableAutomaticTypingAcquisition: true, tsserver: { fallbackPath: require.resolve("typescript/lib/tsserver.js"), useSyntaxServer: "never" },
      preferences: { includePackageJsonAutoImports: "off" } },
  }).then(() => connection.sendNotification("initialized", {})).catch((error) => { stop(); throw error })
  // Attach a handler immediately; initialization can fail before the first query.
  void ready.catch(() => {})
  const documents = new Map<string, { text: string; version: number }>()
  const allowed = new Set<string>()
  let queue = Promise.resolve()
  let touched = Date.now()
  const authorizedPath = async (path: string, workspace: boolean) => {
    const canonical = await realpath(resolve(root, path))
    if (!(workspace && inside(root, canonical)) && !allowed.has(canonical)) {
      throw new Error(workspace ? "The source file must be inside this workspace or an authorized language-service target." : "Peek target expired. Run the lookup again.")
    }
    return canonical
  }
  // Every position query shares document validation/synchronization and the same
  // serialized queue. New query types must not implement a parallel stale buffer.
  const withDocument = <T>(input: PositionQuery, signal: AbortSignal | undefined, run: (uri: string, path: string) => Promise<T>) => {
    touched = Date.now()
    const work = queue.then(async (): Promise<T> => {
      await ready
      signal?.throwIfAborted()
      const path = await authorizedPath(input.path, true)
      if (!supportedSource(path)) throw new Error("Language queries currently support TypeScript and JavaScript files.")
      const text = await readSource(path, signal)
      const lines = text.split(/\r?\n/)
      if (!Number.isInteger(input.line) || input.line < 0 || !Number.isInteger(input.character) || input.character < 0
        || lines[input.line] !== input.expectedLine.replace(/\r?\n$/, "") || input.character >= (lines[input.line]?.length ?? 0)) {
        throw new Error("The displayed source no longer matches the working-copy file. Refresh it and try again.")
      }
      // Refresh other opened files too: external edits must not leave tsserver's
      // in-memory buffers stale. The open-document set is bounded below.
      for (const [uri, previous] of documents) {
        let contents: string
        try { contents = await readSource(fileURLToPath(uri)) } catch {
          await connection.sendNotification("textDocument/didClose", { textDocument: { uri } })
          documents.delete(uri)
          continue
        }
        if (contents === previous.text) continue
        previous.text = contents
        previous.version++
        await connection.sendNotification("textDocument/didChange", { textDocument: { uri, version: previous.version }, contentChanges: [{ text: contents }] })
      }
      const uri = pathToFileURL(path).href
      if (!documents.has(uri)) {
        if (documents.size >= 16) {
          const oldest = documents.keys().next().value!
          await connection.sendNotification("textDocument/didClose", { textDocument: { uri: oldest } })
          documents.delete(oldest)
        }
        documents.set(uri, { text, version: 1 })
        const languageId = /\.tsx$/i.test(path) ? "typescriptreact" : /\.jsx$/i.test(path) ? "javascriptreact" : /\.[cm]?ts$/i.test(path) ? "typescript" : "javascript"
        await connection.sendNotification("textDocument/didOpen", { textDocument: { uri, languageId, version: 1, text } })
      }
      signal?.throwIfAborted()
      return run(uri, path)
    })
    queue = work.then(() => {}, () => {})
    return work
  }
  const lookup = (input: PositionQuery & { kind: LookupKind }, signal?: AbortSignal) => withDocument(input, signal, async (uri, path): Promise<PeekResult> => {
    if (!lookupKinds.includes(input.kind)) throw new Error("Unsupported language query.")
    const value = await request<Location | Location[] | { range: Range }[] | null>(`textDocument/${input.kind}`, {
      textDocument: { uri }, position: { line: input.line, character: input.character },
      ...(input.kind === "references" ? { context: { includeDeclaration: false } } : {}),
    }, signal)
    const all = normalizeLocations(input.kind === "documentHighlight"
      ? ((value ?? []) as { range: Range }[]).map((highlight) => ({ uri, range: highlight.range }))
      : value as Location | Location[] | null)
    const candidates = all.slice(0, limit)
    // External files must be LSP-returned targets. Authorize canonical paths,
    // never mutable symlink aliases; deduplicate filesystem work for references.
    if (allowed.size > 10000) allowed.clear()
    const canonicalPaths = await Promise.all([...new Set(candidates.map((location) => location.path))].map(async (path) => {
      try { return [path, await realpath(path)] as const } catch { return [path, path] as const }
    }))
    const paths = new Map(canonicalPaths)
    for (const [, path] of canonicalPaths) allowed.add(path)
    const locations = candidates.map((location) => ({ ...location, path: paths.get(location.path) ?? location.path }))
    return { locations, truncated: all.length > limit, sameFile: all.length > 0 && all.every((location) => (paths.get(location.path) ?? location.path) === path) }
  })
  const hover = (input: PositionQuery, signal?: AbortSignal) => withDocument(input, signal, async (uri): Promise<HoverResult> => {
    const value = await request<{ contents: HoverContents } | null>("textDocument/hover", {
      textDocument: { uri }, position: { line: input.line, character: input.character },
    }, signal)
    return { text: hoverText(value) }
  })
  return { lookup, hover, stop, ready, get stopped() { return stopped }, get touched() { return touched },
    async document(path: string, signal?: AbortSignal): Promise<SourceDocument> {
      touched = Date.now()
      const canonical = await authorizedPath(path, true)
      return { path: canonical, text: await readSource(canonical, signal), queryable: supportedSource(canonical) }
    },
    async source(path: string, line: number) {
      touched = Date.now()
      const lines = (await readSource(await authorizedPath(path, false))).split(/\r?\n/)
      const startLine = Math.max(0, Math.min(line, lines.length - 1) - 8)
      return { startLine, lines: lines.slice(startLine, Math.min(lines.length, line + 24)) }
    },
  }
}

export async function setupIntelligence(ctx: Plugin.Context) {
  const services = new Map<string, ReturnType<typeof createLanguageService>>()
  const restarts = new Map<string, Promise<void>>()
  const service = async (directory: string) => {
    const root = await realpath(directory)
    let value = services.get(root)
    if (!value || value.stopped) {
      if (services.size >= 4) {
        const oldest = [...services].sort((a, b) => a[1].touched - b[1].touched)[0]
        oldest[1].stop()
        services.delete(oldest[0])
      }
      value = createLanguageService(root)
      services.set(root, value)
    }
    return value
  }
  const registration = await ctx.rpc.register(Intelligence, {
    document: async (input, context) => {
      const { directory, path } = input as { directory: string; path: string }
      const root = await realpath(directory)
      const existing = services.get(root)
      if (existing && !existing.stopped) return existing.document(path, context.signal)
      // Browsing a workspace file does not start a language-server process.
      // Outside-workspace dependencies require a still-live authorization.
      const canonical = await realpath(resolve(root, path))
      if (!inside(root, canonical)) throw new Error("Peek target expired. Run the lookup again.")
      return { path: canonical, text: await readSource(canonical, context.signal), queryable: supportedSource(canonical) }
    },
    hover: async (input, context) => {
      const value = input as PositionQuery & { directory: string }
      return (await service(value.directory)).hover(value, context.signal)
    },
    restart: async (input) => {
      const { directory } = input as { directory: string }
      const root = await realpath(directory)
      let pending = restarts.get(root)
      if (!pending) {
        pending = (async () => {
          // Drop the entire instance, including open documents, queues and
          // authorized source targets. Never wait on a wedged lookup queue.
          services.get(root)?.stop()
          services.delete(root)
          const replacement = await service(root)
          await registration.events.emit("restarted", { directory, root })
          await replacement.ready
        })()
        restarts.set(root, pending)
      }
      try {
        await pending
        return { restarted: true }
      } finally { if (restarts.get(root) === pending) restarts.delete(root) }
    },
    lookup: async (input, context) => {
      const value = input as { directory: string; path: string; line: number; character: number; expectedLine: string; kind: LookupKind }
      return (await service(value.directory)).lookup(value, context.signal)
    },
    source: async (input) => {
      const value = input as { directory: string; path: string; line: number }
      const existing = services.get(await realpath(value.directory))
      if (!existing || existing.stopped) throw new Error("Peek target expired. Run the lookup again.")
      return existing.source(value.path, value.line)
    },
  })
  const timer = setInterval(() => {
    for (const [root, value] of services) {
      if (Date.now() - value.touched < 10 * 60_000) continue
      value.stop()
      services.delete(root)
    }
  }, 60_000)
  timer.unref()
  return () => { clearInterval(timer); for (const value of services.values()) value.stop(); void registration.dispose() }
}

import type { Plugin } from "@opencode/plugin"
import { Status } from "./rpc.ts"
import { readOverview, readStatus } from "./status.ts"
import { commit } from "./commit.ts"
import { readDiffContext, readRevisionDiff } from "./diff/server.ts"
import { readChangedFiles } from "./changed-files.ts"
import { readTree } from "./tree/server.ts"
import { abandon } from "./tree/abandon.ts"
import { describe } from "./tree/describe.ts"
import { newChange } from "./tree/new.ts"
import { listBookmarks, setBookmark } from "./tree/bookmarks.ts"
import { editChange } from "./tree/edit.ts"
import { readSquashDetails, squashBelow } from "./tree/squash.ts"
import { pushChange } from "./tree/push.ts"
import { readFileChanges } from "./file-changes.ts"
import { diffBaseOption } from "./diff/base.ts"
import { checkoutPR } from "./checkout-pr.ts"

export async function setupJJ(ctx: Plugin.Context) {
  const diffBase = diffBaseOption(ctx.options.jjDiffBase)
  await ctx.rpc.register(Status, {
    checkoutPR: async (input, context) => {
      const { directory, pull } = input as { directory: string; pull: string }
      return checkoutPR(directory, pull, context.signal)
    },
    fileChanges: async (input, context) => {
      const { directory, path } = input as { directory: string; path: string }
      return readFileChanges(directory, path, context.signal)
    },
    diffContext: async (input, context) => {
      const { directory, commitID, path, baseCommitID } = input as { directory: string; commitID: string; path: string; baseCommitID?: string }
      return readDiffContext(directory, commitID, path, context.signal, baseCommitID)
    },
    gitPush: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID: string }
      await pushChange(directory, commitID, context.signal)
      return { pushed: true }
    },
    squashDetails: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID: string }
      return readSquashDetails(directory, commitID, context.signal)
    },
    squashBelow: async (input, context) => {
      const { directory, commitID, parentID, message } = input as { directory: string; commitID: string; parentID: string; message?: string }
      await squashBelow(directory, commitID, parentID, message, context.signal)
      return { squashed: true }
    },
    edit: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID: string }
      await editChange(directory, commitID, context.signal)
      return { edited: true }
    },
    bookmarks: async (input, context) => {
      const { directory } = input as { directory: string }
      return listBookmarks(directory, context.signal)
    },
    setBookmark: async (input, context) => {
      const { directory, commitID, name } = input as { directory: string; commitID: string; name: string }
      await setBookmark(directory, commitID, name, context.signal)
      return { set: true }
    },
    revisionFiles: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID: string }
      return readChangedFiles(directory, context.signal, commitID)
    },
    newChange: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID?: string }
      await newChange(directory, context.signal, commitID)
      return { created: true }
    },
    describe: async (input, context) => {
      const { directory, commitID, message } = input as { directory: string; commitID: string; message: string }
      await describe(directory, commitID, message, context.signal)
      return { described: true }
    },
    abandon: async (input, context) => {
      const { directory, commitID } = input as { directory: string; commitID: string }
      await abandon(directory, commitID, context.signal)
      return { abandoned: true }
    },
    tree: async (input, context) => {
      const { directory, limit, revset } = input as { directory: string; limit: number; revset?: string }
      return readTree(directory, limit, context.signal, revset)
    },
    changedFiles: async (input, context) => {
      const { directory } = input as { directory: string }
      return readChangedFiles(directory, context.signal)
    },
    diff: async (input, context) => {
      const { directory, commitID, changeID, knownCommitID, againstMain, knownBaseCommitID } = input as {
        directory: string; commitID?: string; changeID?: string; knownCommitID?: string; againstMain?: boolean; knownBaseCommitID?: string
      }
      if (commitID && changeID) throw new Error("Supply a commit ID or change ID, not both.")
      return readRevisionDiff(directory, changeID ?? commitID ?? "", context.signal, knownCommitID, { againstMain, knownBaseCommitID, diffBase })
    },
    commit: async (input, context) => {
      const { directory, message } = input as { directory: string; message: string }
      await commit(directory, message, context.signal)
      return { committed: true }
    },
    overview: async (input, context) => {
      const { directory } = input as { directory: string }
      return readOverview(directory, context.signal)
    },
    status: async (input, context) => {
      const { directory } = input as { directory: string }
      return readStatus(directory, context.signal)
    },
  })
}

import { runJJ, validateCommitID } from "../command.ts"
import { parseRevisions, revisionTemplate, type Revision } from "../overview.ts"
import { resolveDiffBase } from "./base.ts"

// Load only the requested file, pinned to the same immutable revision as the
// initial patch. A full-context diff also handles merged parents correctly.
export async function readDiffContext(directory: string, commitID: string, path: string, signal?: AbortSignal, baseCommitID?: string): Promise<{ patch: string }> {
  validateCommitID(commitID, "Invalid commit ID")
  if (baseCommitID !== undefined) validateCommitID(baseCommitID, "Invalid base commit ID")
  if (!path || path.includes("\0") || path.startsWith("/") || path.split("/").some((part) => part === "..")) throw new Error("Invalid file path")
  const result = await runJJ(["diff", "--ignore-working-copy", "--git", "--context=2147483647",
    ...(baseCommitID ? ["--from", baseCommitID, "--to", commitID] : ["-r", commitID]),
    "--", `file:${JSON.stringify(path)}`], { cwd: directory, signal, timeout: 30_000, maxBuffer: 16 * 1024 * 1024 })
  return { patch: result.stdout }
}

export interface RevisionDiff {
  patch: string
  revision: Revision
  workingCopySource?: boolean
  baseCommitID?: string
  baseBranch?: string
  unchanged?: boolean
}

const identityTemplate = [
  '"{"',
  "'\"commitID\":' ++ json(self.commit_id())",
  "',\"changeID\":' ++ json(self.change_id())",
  "',\"current\":' ++ json(current_working_copy)",
  "',\"divergent\":' ++ json(divergent)",
  "',\"empty\":' ++ json(empty)",
  "',\"parents\":' ++ json(parents.map(|parent| parent.commit_id()))",
  '"}\\n"',
].join(" ++ ")

export async function readRevisionDiff(directory: string, commitID: string, signal?: AbortSignal, knownCommitID?: string,
  comparison?: { againstMain?: boolean; knownBaseCommitID?: string; diffBase?: string }): Promise<RevisionDiff> {
  // Normal tabs follow a full change ID; divergent tabs pin an exact commit.
  // Never accept arbitrary revsets, abbreviations, or options.
  const byChange = /^(?:[k-z]{32}|[k-z]{64})$/.test(commitID)
  if (!byChange) validateCommitID(commitID, "Invalid commit ID or change ID")
  if (knownCommitID !== undefined) validateCommitID(knownCommitID, "Invalid known commit ID")
  if (comparison?.knownBaseCommitID !== undefined) validateCommitID(comparison.knownBaseCommitID, "Invalid known base commit ID")
  const options = { cwd: directory, signal, timeout: 30_000, maxBuffer: 16 * 1024 * 1024 }
  // A working-copy snapshot rewrites its commit hash. Compare full change IDs
  // so this tab follows that change only while it is still the working copy.
  const identities = await runJJ(["log", "--ignore-working-copy", "--no-graph",
    "-r", `${commitID} | @`, "-T", identityTemplate], options)
  const commits = identities.stdout.split("\n").filter(Boolean).map((line) => JSON.parse(line) as {
    commitID: string; changeID: string; current: boolean; divergent: boolean; empty: boolean; parents: string[]
  })
  const matches = commits.filter((commit) => byChange ? commit.changeID === commitID : commit.commitID === commitID)
  if (matches.length !== 1) throw new Error("Change not found or divergent. Reopen a specific version from JJ Tree.")
  const original = matches[0]
  const current = commits.find((commit) => commit.current)
  const live = !!original && original.changeID === current?.changeID && !original.divergent && !current.divergent
  const emptyParent = current?.empty && current.parents.length === 1 && current.parents[0] === original.commitID
  // Only snapshot historical tabs when they may be the source of an empty @.
  // Check again after snapshotting: unrecorded edits can make @ non-empty.
  let workingCopySource = live
  if (!live && emptyParent) {
    const snapshot = await runJJ(["log", "--no-graph", "-r", "@", "-T", identityTemplate], options)
    const checkout = JSON.parse(snapshot.stdout.trim()) as typeof original
    workingCopySource = checkout.empty && checkout.parents.length === 1 && checkout.parents[0] === original.commitID
  }
  // Pin both metadata and patch to an exact commit. Only live tabs follow @;
  // the empty-parent check above never changes a historical tab's revision.
  const metadata = await runJJ(["log", ...(!live ? ["--ignore-working-copy"] : []), "--no-graph",
    "-r", live ? "@" : original.commitID, "-T", revisionTemplate], options)
  const revision = parseRevisions(metadata.stdout)[0]
  if (!revision) throw new Error("Revision not found")
  let baseCommitID: string | undefined
  let baseBranch: string | undefined
  if (comparison?.againstMain) {
    const branch = await resolveDiffBase(options, comparison.diffBase)
    baseBranch = branch.label
    // Three-dot/PR semantics: default-branch-only changes must not appear as reversals.
    // Pin the base too, so context expansion never resolves a moved bookmark.
    const bases = await runJJ(["log", "--ignore-working-copy", "--no-graph",
      "-r", `heads(::${branch.commitID} & ::${revision.commitID})`, "-T", 'commit_id ++ "\\n"'], options)
    const ids = bases.stdout.trim().split("\n").filter(Boolean)
    if (ids.length !== 1) throw new Error(`PR diff requires a single common ancestor with ${baseBranch}.`)
    baseCommitID = ids[0]
  }
  const base = baseCommitID ? { baseCommitID, ...(baseBranch ? { baseBranch } : {}) } : {}
  // The client already holds the patch for this immutable hash. Avoid the
  // expensive diff command and sending megabytes over the remote connection.
  if (revision.commitID === knownCommitID && baseCommitID === comparison?.knownBaseCommitID)
    return { revision, workingCopySource, ...base, patch: "", unchanged: true }
  const diff = await runJJ(["diff", "--ignore-working-copy", "--git", "--context=6",
    ...(baseCommitID ? ["--from", baseCommitID, "--to", revision.commitID] : ["-r", revision.commitID])], options)
  return { patch: diff.stdout, revision, workingCopySource, ...base }
}

import { runJJ } from "../command.ts"
import { parseHistory, treeTemplate, type TreeHistory } from "./model.ts"
import { normalizeTreeRevset } from "./revset.ts"

export async function readTree(directory: string, limit: number, signal?: AbortSignal, revset = ""): Promise<TreeHistory> {
  const revisions = normalizeTreeRevset(revset)
  const { stdout } = await runJJ([
    "log", "--no-graph", "--limit", String(limit + 1), "--template", treeTemplate,
    // A single argv value, never shell text or another JJ option.
    ...(revisions ? [`--revisions=${revisions}`] : []),
  ], { cwd: directory, signal, timeout: 15_000, maxBuffer: 16 * 1024 * 1024 })
  return parseHistory(stdout, limit)
}
